'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected='',category='All',directoryScroll=0,readingScroll=0;
function list(){
 updateIndex();if(indexMode()!=="lessons")return;
 const words=$('#search').value.toLowerCase().trim().split(/\s+/).filter(Boolean);
 const items=LESSONS.filter(a=>(category==='All'||a.category===category)&&words.every(w=>(a.title+' '+a.summary+' '+a.search+' ').toLowerCase().includes(w)));
 const filtering=words.length>0||category!=='All';
 const current=LESSONS.find(a=>a.slug===selected)||LESSONS.find(a=>a.id===pathIds[0]);
 $('#count').textContent=filtering?items.length+' '+(items.length===1?'lesson':'lessons')+' found':pathIds.length+' lessons in order';
 $('#empty').hidden=items.length>0;
 const done=pathIds.filter(id=>progress[id]).length;
 $('#sidebar-progress').textContent=done+' of '+pathIds.length+' practised';
 $('#sidebar-meter').max=pathIds.length;$('#sidebar-meter').value=done;
 $('#topics').innerHTML=LEARNING_PATH.map((stage,i)=>{
  const lessons=stage.ids.map(id=>items.find(a=>a.id===id)).filter(Boolean);
  if(!lessons.length)return '';
  return `<details class="group" ${filtering||stage.ids.includes(current.id)?'open':''}><summary><span class="stage-number" aria-hidden="true">${i+1}</span><span><h2><span>Stage ${i+1}</span>${esc(stage.title)}</h2><span class="stage-progress">${stage.ids.filter(id=>progress[id]).length} of ${stage.ids.length} practised</span></span><span class="stage-chevron" aria-hidden="true">⌄</span></summary><ol>${lessons.map(a=>{
   const active=location.hash==='#/lesson/'+a.slug||a.aliases.some(alias=>location.hash==='#/lesson/'+alias)||((!location.hash||location.hash==='#/')&&a.slug===(selected||LESSONS.find(l=>l.id==='MI01').slug));
   return `<li><a class="topic" href="#/lesson/${a.slug}" ${active?'aria-current="page"':''}><span class="lesson-number" aria-hidden="true">${pathIds.indexOf(a.id)+1}</span><span><strong>${esc(a.title)}</strong><small>${a.minutes} min · ${esc(a.category)}${progress[a.id]?' · Practised ✓':''}</small>${active?'<span class="readingtag">Reading now</span>':''}</span></a></li>`;
  }).join('')}</ol></details>`;
 }).join('');
 document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===category));
}
function snapshot(){return {directoryQueries:{...directoryQueries},selected,category,query:$('#search').value,view:document.body.dataset.view,ds:$('.browser').clientHeight?$('.browser').scrollTop:directoryScroll,rs:$('.reader').clientHeight?$('.reader').scrollTop:readingScroll};}
function save(){history.replaceState(snapshot(),'');}
const pathIds=LEARNING_PATH.flatMap(s=>s.ids);
let progress={};let storageAvailable=true;
try{const stored=JSON.parse(localStorage.getItem('league-guide-progress-v1')||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored))progress=stored;}catch(e){storageAvailable=false;}
function persistProgress(){try{localStorage.setItem('league-guide-progress-v1',JSON.stringify(progress));}catch(e){storageAvailable=false;}}
let quizResults={};
try { const stored=JSON.parse(localStorage.getItem('league-guide-quizzes-v1')||'{}'); if(stored&&typeof stored==='object'&&!Array.isArray(stored))quizResults=stored; } catch (_) {}
function persistQuizzes(){try{localStorage.setItem('league-guide-quizzes-v1',JSON.stringify(quizResults));}catch(_){storageAvailable=false;}}
function validAttempt(stage){const a=quizResults[stage.ids[0]];return Array.isArray(a)&&a.length===stage.quiz.length&&a.every((v,i)=>Number.isInteger(v)&&v>=0&&v<stage.quiz[i].options.length)?a:null;}
function quizMarkup(stage){
 const key=stage.ids[0],attempt=validAttempt(stage),score=attempt?attempt.filter((v,i)=>v===stage.quiz[i].answer).length:0;
 return `<form class="stage-quiz" data-stage="${key}" aria-label="${esc(stage.title)} quiz"><h3>Stage ${LEARNING_PATH.indexOf(stage)+1} quiz</h3><p>Choose one answer for each scenario, then check your answers. You can retry or continue at any time.</p>${stage.quiz.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.prompt)}</legend>${q.options.map((option,j)=>`<label><input type="radio" name="${key}-${i}" value="${j}" required ${attempt&&attempt[i]===j?'checked':''} ${attempt?'disabled':''}><span>${esc(option)}</span></label>`).join('')}${attempt?`<p class="quiz-explanation"><strong>${attempt[i]===q.answer?'Correct.':'Review this.'}</strong> ${esc(q.explanation)} <strong>Answer:</strong> ${esc(q.options[q.answer])} <a href="#/lesson/${LESSONS.find(a=>a.id===q.review).slug}">Review ${esc(LESSONS.find(a=>a.id===q.review).title)}</a></p>`:''}</fieldset>`).join('')}<p class="quiz-result" role="status" tabindex="-1">${attempt?`${score} of ${stage.quiz.length} correct. ${score===stage.quiz.length?'Now try the replay drill.':'Read the explanations, review the linked lessons, then retry.'}`:''}</p>${attempt?'<button type="button" data-retry="'+key+'">Retry quiz</button>':'<button type="submit">Check answers</button>'}<p class="note">${storageAvailable?'Your latest checked answers are saved in this browser when storage is available.':'Storage is unavailable; quiz results last for this page only.'} Quiz results are separate from practice marks and do not certify mastery.</p></form>`;
}
function stageContent(stage){const x=stage.extension;return `<div class="stage-extension"><h3>Worked scenario: ${esc(x.title)}</h3><p class="note">Hypothetical example · Apply the lessons together</p><p>${esc(x.scenario)}</p><h4>Reason through the decision</h4><p>${esc(x.walkthrough)}</p><h4>Replay drill</h4><p>${esc(x.drill)}</p></div>${quizMarkup(stage)}`;}
document.addEventListener('submit',e=>{const form=e.target.closest('.stage-quiz');if(!form)return;e.preventDefault();const stage=LEARNING_PATH.find(s=>s.ids[0]===form.dataset.stage);const answers=stage.quiz.map((_,i)=>Number(new FormData(form).get(stage.ids[0]+'-'+i)));quizResults[stage.ids[0]]=answers;persistQuizzes();form.outerHTML=quizMarkup(stage);$(`form[data-stage="${stage.ids[0]}"] .quiz-result`).focus({preventScroll:true});});
document.addEventListener('click',e=>{const button=e.target.closest('[data-retry]');if(!button)return;const stage=LEARNING_PATH.find(s=>s.ids[0]===button.dataset.retry);delete quizResults[stage.ids[0]];persistQuizzes();button.closest('form').outerHTML=quizMarkup(stage);$(`form[data-stage="${stage.ids[0]}"] input`).focus({preventScroll:true});});
const themeButton=$('#theme-toggle');
function themeLabel(){const dark=document.documentElement.dataset.theme==='dark';themeButton.setAttribute('aria-pressed',dark);themeButton.textContent=dark?'Light mode':'Dark mode';themeButton.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');}
themeButton.onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('league-guide-theme-v1',document.documentElement.dataset.theme);}catch(_){}themeLabel();};themeLabel();
function pathFooter(a){const i=pathIds.indexOf(a.id),stage=LEARNING_PATH.find(s=>s.ids.includes(a.id));const next=LESSONS.find(l=>l.id===pathIds[i+1]);return `<section class="path-controls"><h2>Keep learning</h2><p>Stage ${LEARNING_PATH.indexOf(stage)+1}: ${esc(stage.title)} · Lesson ${i+1} of ${pathIds.length}</p><button id="complete" data-id="${a.id}" aria-pressed="${!!progress[a.id]}">${progress[a.id]?'Practised ✓ · Undo':'Mark as practised'}</button><p class="note">Mark this after trying the exercise. It records practice, not mastery.</p>${stage.ids.at(-1)===a.id?`<h3>Stage checkpoint</h3><p>${esc(stage.check)}</p>${stageContent(stage)}`:''}<nav class="next" aria-label="Learning path navigation"><a href="#/path">View learning path</a>${next?`<a href="#/lesson/${next.slug}">Next: ${esc(next.title)} →</a>`:'<a href="#/path">Review your checkpoints →</a>'}</nav></section>`;}
function pathPage(){const done=pathIds.filter(id=>progress[id]).length;const next=LESSONS.find(a=>a.id===pathIds.find(id=>!progress[id]));$('#content').innerHTML=`<article class="article learning-path"><div class="eyebrow">${LEARNING_PATH.length} stages · ${pathIds.length} concepts</div><h1 tabindex="-1">Your learning path.</h1><p class="lead">Build one skill at a time. Read a lesson, try its exercise, then review your decision.</p><p>Start with basic movement and attacks. This general path uses lane examples; supports and junglers can use replays for lane drills. You can revisit or skip any lesson.</p><p id="progress-count" role="status">${done} of ${pathIds.length} lessons practised</p><progress max="${pathIds.length}" value="${done}" aria-label="Lessons practised"></progress><p class="note">${storageAvailable?'Progress is saved in this browser when storage is available. It does not sync between devices; moving the offline folder can change storage access.':'Browser storage is unavailable. Progress lasts for this open page only.'}</p>${next?`<a class="primary" href="#/lesson/${next.slug}">${done?'Continue':'Start'}: ${esc(next.title)} →</a>`:'<p>All lessons practised. Revisit the checkpoints and pick one skill to repeat in your next game.</p>'}${LEARNING_PATH.map((s,i)=>`<section><div class="eyebrow">Stage ${i+1}</div><h2>${esc(s.title)}</h2><p>${esc(s.goal)}</p><p class="note">${i?'Builds on the earlier stages. Revisit them when a drill exposes a gap.':'Prerequisite: basic movement and attacks.'}</p><ol>${s.ids.map(id=>{const a=LESSONS.find(a=>a.id===id);return `<li><a href="#/lesson/${a.slug}">${esc(a.title)}</a> <span class="note">${a.minutes} min read${progress[id]?' · Practised ✓':''}</span></li>`;}).join('')}</ol><div class="checkpoint"><h3>Before you move on</h3><p>${esc(s.check)}</p></div>${stageContent(s)}</section>`).join('')}<button id="reset-progress">Reset practice progress</button><p id="reset-message" role="status"></p></article>`;document.title='Learning path — League.guide';}
function article(a){$('#content').innerHTML=`<article class="article"><div class="eyebrow">${a.category} / ${a.minutes} min read</div><h1 tabindex="-1">${esc(a.title)}</h1><p class="lead">${esc(a.summary)}</p><details><summary>Who this lesson is for</summary>${Object.entries(a.meta).filter(([k,v])=>v).map(([k,v])=>`<p><strong>${({roles:'Roles',skill_level:'Level',prerequisites:'Prerequisites',action:'Observable action'})[k]}:</strong> ${esc(v)}</p>`).join('')}</details>${a.html}${pathFooter(a)}</article>`;document.title=a.title+' — League.guide';}
function render(state,initial=false){if(state?.directoryQueries)directoryQueries={...state.directoryQueries};if(renderDirectory(state,initial))return;const slug=location.hash.replace(/^#\/lesson\//,'');const a=LESSONS.find(a=>a.slug===slug||a.aliases.includes(slug));if(state){selected=state.selected;category=state.category;$('#search').value=state.query;directoryScroll=state.ds;readingScroll=state.rs;}else if(a){selected=a.slug;readingScroll=0;}const isPath=location.hash==='#/path';const unknown=location.hash.startsWith('#/lesson/')&&!a;const current=LESSONS.find(a=>a.slug===selected)||LESSONS.find(a=>a.id==='MI01');document.body.dataset.view=a?'article':'list';if(isPath){pathPage();document.body.dataset.view='article';}else if(unknown){$('#content').innerHTML='<article class="article"><h1 tabindex="-1">Lesson not found.</h1><p>This link does not match a lesson in the library.</p><a href="#/">Browse all lessons →</a></article>';document.body.dataset.view='article';document.title='Lesson not found — League.guide';}else{article(current);if(!a)document.title='League.guide — Reading library';}list();$('#resume').hidden=!selected;$('#resume').textContent='Continue reading: '+current.title+' →';$('.browser').scrollTop=directoryScroll;$('.reader').scrollTop=readingScroll;if(!initial){if(a||unknown||isPath)$('.article h1').focus({preventScroll:true});else ($(`.topic[href="#/lesson/${selected}"]`)||$('#search')).focus({preventScroll:true});}}
function go(hash){save();directoryScroll=snapshot().ds;readingScroll=snapshot().rs;const match=LESSONS.find(a=>a.aliases.includes(hash.slice(9)));if(match)hash='#/lesson/'+match.slug;const isLesson=hash.startsWith('#/lesson/');if((isLesson&&hash!=='#/lesson/'+selected)||hash!==location.hash&&(/^#\/(champion|matchup)/.test(hash)||indexMode()!=='lessons')){readingScroll=0;directoryScroll=0;}history.pushState(null,'',hash);render({...snapshot(),selected:isLesson?hash.slice(9):selected,ds:directoryScroll,rs:readingScroll});save();}
function reset(){category='All';$('#search').value='';list();directoryScroll=0;$('.browser').scrollTop=0;$('#search').focus();save();}
$('#search').oninput=()=>{list();save();};$('#all').onclick=reset;$('#reset').onclick=reset;$('#return').onclick=()=>go(indexMode()==='lessons'?'#/':'#/'+indexMode());$('#resume').onclick=()=>go('#/lesson/'+selected);document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;list();save();});document.addEventListener('click',e=>{const complete=e.target.closest('#complete');if(complete){const id=complete.dataset.id;progress[id]=!progress[id];persistProgress();complete.setAttribute('aria-pressed',!!progress[id]);complete.textContent=progress[id]?'Practised ✓ · Undo':'Mark as practised';list();return;}if(e.target.closest('#reset-progress')){progress={};persistProgress();pathPage();list();$('#reset-progress').focus();$('#reset-message').textContent='Practice progress reset.';return;}const a=e.target.closest('a');if(!a||!a.getAttribute('href').startsWith('#/')||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();go(a.getAttribute('href'));});window.addEventListener('popstate',e=>render(e.state));render(history.state,true);save();
